#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const indexPath = path.join(repoRoot, "index.html");
const inventoryPath = path.join(repoRoot, "guide-inventory.json");
const indexSource = fs.readFileSync(indexPath, "utf8");
const phaseStart = indexSource.indexOf("const R=");
const phaseEnd = indexSource.indexOf("const LIBRARY=");
if (phaseStart < 0 || phaseEnd < 0) throw new Error("Could not locate curriculum data");

const sandbox = {};
vm.runInNewContext(
  `${indexSource.slice(phaseStart, phaseEnd)}\nglobalThis.__PHASES__ = PHASES;`,
  sandbox,
  { filename: indexPath },
);

const inventory = JSON.parse(fs.readFileSync(inventoryPath, "utf8"));
const targetByMarker = new Map(inventory.topics.map((topic) => [topic.marker, topic.target]));
const topicByMarker = new Map();
for (const phase of sandbox.__PHASES__) {
  for (const week of phase.weeks) {
    for (const topic of week.topics) topicByMarker.set(topic.mk, { phase, week, topic });
  }
}

